import{_ as n,C as a,o as i,c as s,a2 as t,E as r}from"./chunks/framework.BSaF8iZ6.js";const m=JSON.parse('{"title":"Generative AI Configuration (Magic AI)","description":"","frontmatter":{},"headers":[],"relativePath":"configuration/generative-ai.md","filePath":"configuration/generative-ai.md","lastUpdated":1789411447000}'),l={name:"configuration/generative-ai.md"};function g(d,e,h,c,u,f){const o=a("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="generative-ai-configuration-magic-ai" tabindex="-1">Generative AI Configuration (Magic AI) <a class="header-anchor" href="#generative-ai-configuration-magic-ai" aria-label="Permalink to &quot;Generative AI Configuration (Magic AI)&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Admin</span><span>Configure &gt;&gt; Magic AI</span></div><p>This page sets up Generative AI for sellers: switching it on, connecting an AI provider, and choosing what sellers may generate and how often. What sellers do with it is described in <a href="./../generative-ai/generate-product-content">Generate Product Content</a>.</p><p>The settings are in the <strong>Magic AI</strong> group of the Configure page. Magic AI is the name the admin panel uses for Bagisto&#39;s Generative AI.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>You need an account with an AI provider and its API key, or your own Ollama server. Three switches must all be on before a seller sees the <strong>Generate content</strong> button:</p><ol><li><strong>Enabled</strong> on <strong>Configure &gt;&gt; Magic AI &gt;&gt; General</strong>.</li><li><strong>Enable</strong> on <strong>Configure &gt;&gt; Magic AI &gt;&gt; Marketplace Features</strong>.</li><li><strong>Magic AI Enabled</strong> on the seller&#39;s own record, which is on unless you turn it off. See <a href="./../generative-ai/usage-limits">Usage Limits</a>.</li></ol><h2 id="switch-on-generative-ai" tabindex="-1">Switch on Generative AI <a class="header-anchor" href="#switch-on-generative-ai" aria-label="Permalink to &quot;Switch on Generative AI&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; General</strong>.</li><li>In <strong>Settings</strong>, switch <strong>Enabled</strong> on.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',9)),r(o,{src:"/images/configuration/magic-ai-general.png",alt:"Magic AI General settings with the Enabled switch"}),e[1]||(e[1]=t('<h2 id="connect-a-provider" tabindex="-1">Connect a provider <a class="header-anchor" href="#connect-a-provider" aria-label="Permalink to &quot;Connect a provider&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; Providers</strong>.</li><li>Enter the <strong>API Key</strong> for each provider you use. For Ollama, enter the <strong>Base URL</strong> of your server (it starts as <code>http://localhost:11434</code>), and an <strong>API Key</strong> only if your server needs one.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',2)),r(o,{src:"/images/configuration/magic-ai-providers.png",alt:"Magic AI Providers settings"}),e[2]||(e[2]=t('<p>The key of the provider that owns the chosen model is used when a seller generates content.</p><h2 id="set-up-content-generation-for-sellers" tabindex="-1">Set up content generation for sellers <a class="header-anchor" href="#set-up-content-generation-for-sellers" aria-label="Permalink to &quot;Set up content generation for sellers&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; Marketplace Features</strong>.</li><li>In <strong>Product Content Generation</strong>, switch <strong>Enable</strong> on.</li><li>Choose the <strong>Model</strong>.</li><li>Set the options below.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',3)),r(o,{src:"/images/configuration/magic-ai-product-content.png",alt:"Product Content Generation section of the Marketplace Features settings"}),e[3]||(e[3]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enable</strong></td><td>The master switch. When off, no seller can generate content, whatever their own setting.</td></tr><tr><td><strong>Model</strong></td><td>The model used when the seller writes a description only.</td></tr><tr><td><strong>Allow Reference Images</strong></td><td>Lets sellers attach product photos for the AI to look at. It is on until you change it.</td></tr><tr><td><strong>Vision Model</strong></td><td>The model used when photos are attached. Choose one that can read images. It appears when <strong>Allow Reference Images</strong> is on. If you leave it empty, the <strong>Model</strong> above is used for photos too.</td></tr><tr><td><strong>Maximum Reference Images</strong></td><td>How many photos a seller can attach to one request. It appears when <strong>Allow Reference Images</strong> is on. Leave it empty to allow 3.</td></tr><tr><td><strong>Let Sellers Choose Fields</strong></td><td>Lets sellers tick which fields to fill. When off, every field that can be generated is filled.</td></tr><tr><td><strong>Overwrite Filled Attributes</strong></td><td>Lets the AI suggest new values for fields that already have one. When off, only empty fields are suggested.</td></tr></tbody></table><h2 id="limit-how-often-and-what-sellers-generate" tabindex="-1">Limit how often and what sellers generate <a class="header-anchor" href="#limit-how-often-and-what-sellers-generate" aria-label="Permalink to &quot;Limit how often and what sellers generate&quot;">​</a></h2>',2)),r(o,{src:"/images/configuration/magic-ai-limits-scope.png",alt:"Limits and Scope sections of the Marketplace Features settings"}),e[4]||(e[4]=t('<table tabindex="0"><thead><tr><th>Section</th><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Limits</td><td><strong>Per Seller Limit</strong></td><td>How many generations each seller can use in the period below. Leave it empty for no limit. You can set a different limit for one seller.</td></tr><tr><td>Limits</td><td><strong>Limit Period</strong></td><td>Whether the limit resets every day (<strong>Daily</strong>) or every month (<strong>Monthly</strong>).</td></tr><tr><td>Scope</td><td><strong>Select Attributes</strong></td><td>Limits generation to the attributes you choose in <strong>Allowed Attributes</strong>, which appears when this is on and needs at least one attribute. When off, every field the seller can edit may be filled.</td></tr><tr><td>Scope</td><td><strong>Suggest Categories</strong></td><td>Lets the AI suggest categories for the product.</td></tr></tbody></table><p>All of these settings apply to every channel.</p><p>Images, files, Yes/No switches, SKU, URL key, product number, tax category, RMA rule and barcode value are never generated, whatever you choose here.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../generative-ai/usage-limits">Usage Limits</a> — turn Generative AI off or set a different limit for one seller, and see how generations are counted.</li><li><a href="./../generative-ai/generate-product-content">Generate Product Content</a> — how sellers use it.</li></ul>',5))])}const _=n(l,[["render",g]]);export{m as __pageData,_ as default};
